// Uploads the built artifact to the release bucket.
//
// The release bucket is private, so uploads are authenticated with the normal
// AWS environment credentials (AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY).
const crypto = require("crypto");
const fs = require("fs");
const https = require("https");
const path = require("path");

const BUCKET = "releases-eu-prod";
const VERSION = require("./version.json").version;
const SERVICE = "s3";
const CONTENT_TYPE = "application/javascript";

function objectName(version) {
  return `app-${version}.js`;
}

function sha256(value, encoding = "hex") {
  return crypto.createHash("sha256").update(value).digest(encoding);
}

function hmac(key, value, encoding) {
  return crypto.createHmac("sha256", key).update(value).digest(encoding);
}

function awsTimestamp(now) {
  return now.toISOString().replace(/[:-]|\.\d{3}/g, "");
}

function signingKey(secret, date, region) {
  const dateKey = hmac(`AWS4${secret}`, date);
  const regionKey = hmac(dateKey, region);
  const serviceKey = hmac(regionKey, SERVICE);
  return hmac(serviceKey, "aws4_request");
}

function credentials() {
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKeyId || !secretAccessKey) {
    throw new Error(
      "AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY must be set to upload the release artifact"
    );
  }
  return { accessKeyId, secretAccessKey, sessionToken: process.env.AWS_SESSION_TOKEN };
}

function awsRegion() {
  const region = process.env.RELEASE_AWS_REGION || process.env.AWS_REGION || process.env.AWS_DEFAULT_REGION;
  if (!region) {
    throw new Error(
      "Set RELEASE_AWS_REGION (or AWS_REGION) to the region containing releases-eu-prod"
    );
  }
  return region;
}

function endpointFor(region) {
  // S3's us-east-1 endpoint does not include the region component.
  return region === "us-east-1"
    ? `${BUCKET}.s3.amazonaws.com`
    : `${BUCKET}.s3.${region}.amazonaws.com`;
}

function upload(body, name, region, credential) {
  const host = endpointFor(region);
  const now = new Date();
  const amzDate = awsTimestamp(now);
  const date = amzDate.slice(0, 8);
  const payloadHash = sha256(body);
  const encodedName = name.split("/").map(encodeURIComponent).join("/");
  const canonicalUri = `/${encodedName}`;

  const headersToSign = {
    "content-type": CONTENT_TYPE,
    host,
    "x-amz-content-sha256": payloadHash,
    "x-amz-date": amzDate,
  };
  if (credential.sessionToken) {
    headersToSign["x-amz-security-token"] = credential.sessionToken;
  }

  const sortedHeaderNames = Object.keys(headersToSign).sort();
  const canonicalHeaders = sortedHeaderNames
    .map((header) => `${header}:${headersToSign[header]}\n`)
    .join("");
  const signedHeaders = sortedHeaderNames.join(";");
  const canonicalRequest = [
    "PUT",
    canonicalUri,
    "",
    canonicalHeaders,
    signedHeaders,
    payloadHash,
  ].join("\n");
  const scope = `${date}/${region}/${SERVICE}/aws4_request`;
  const stringToSign = ["AWS4-HMAC-SHA256", amzDate, scope, sha256(canonicalRequest)].join("\n");
  const signature = hmac(signingKey(credential.secretAccessKey, date, region), stringToSign, "hex");

  const authorization = [
    "AWS4-HMAC-SHA256",
    `Credential=${credential.accessKeyId}/${scope},`,
    `SignedHeaders=${signedHeaders},`,
    `Signature=${signature}`,
  ].join(" ");

  const requestHeaders = {
    "Content-Type": CONTENT_TYPE,
    "Content-Length": body.length,
    "X-Amz-Content-Sha256": payloadHash,
    "X-Amz-Date": amzDate,
    Authorization: authorization,
  };
  if (credential.sessionToken) {
    requestHeaders["X-Amz-Security-Token"] = credential.sessionToken;
  }

  return new Promise((resolve, reject) => {
    const request = https.request(
      { host, method: "PUT", path: canonicalUri, headers: requestHeaders },
      (response) => {
        response.resume();
        response.on("end", () => {
          if (response.statusCode >= 200 && response.statusCode < 300) {
            resolve();
          } else {
            reject(new Error(`S3 upload failed with HTTP ${response.statusCode}`));
          }
        });
      }
    );
    request.on("error", reject);
    request.end(body);
  });
}

async function main() {
  const body = fs.readFileSync(path.join(__dirname, "dist", "app.js"));
  const name = objectName(VERSION);
  await upload(body, name, awsRegion(), credentials());
  console.log(`uploaded s3://${BUCKET}/${name} (${body.length} bytes)`);
}

main().catch((error) => {
  console.error(`upload failed: ${error.message}`);
  process.exitCode = 1;
});
